// This file is part of the uutils coreutils package.
//
// For the full copyright and license information, please view the LICENSE
// file that was distributed with this source code.

// spell-checker:ignore (ToDO) ugoa cmode

use clap::builder::ValueParser;
use clap::parser::ValuesRef;
use clap::{crate_version, Arg, ArgAction, ArgMatches, Command};
use std::ffi::OsString;
use std::path::{Path, PathBuf};
#[cfg(not(windows))]
use uucore::error::FromIo;
use uucore::error::{UResult, USimpleError};
#[cfg(not(windows))]
use uucore::mode;
use uucore::{
    display::Quotable,
    fs::{dir_strip_dot_for_creation, FileInformation},
};
use uucore::{format_usage, help_about, help_section, help_usage, show_if_err};

static DEFAULT_PERM: u32 = 0o777;

const ABOUT: &str = help_about!("mkdir.md");
const USAGE: &str = help_usage!("mkdir.md");
const AFTER_HELP: &str = help_section!("after help", "mkdir.md");

mod options {
    pub const MODE: &str = "mode";
    pub const PARENTS: &str = "parents";
    pub const VERBOSE: &str = "verbose";
    pub const DIRS: &str = "dirs";
}

#[cfg(windows)]
fn get_mode(_matches: &ArgMatches, _mode_had_minus_prefix: bool) -> Result<u32, String> {
    Ok(DEFAULT_PERM)
}

#[cfg(not(windows))]
fn get_mode(matches: &ArgMatches, mode_had_minus_prefix: bool) -> Result<u32, String> {
    // Not tested on Windows
    let mut new_mode = DEFAULT_PERM;

    if let Some(m) = matches.get_one::<String>(options::MODE) {
        for mode in m.split(',') {
            if mode.chars().any(|c| c.is_ascii_digit()) {
                new_mode = mode::parse_numeric(new_mode, m, true)?;
            } else {
                let cmode = if mode_had_minus_prefix {
                    // clap parsing is finished, now put prefix back
                    format!("-{mode}")
                } else {
                    mode.to_string()
                };
                new_mode = mode::parse_symbolic(new_mode, &cmode, mode::get_umask(), true)?;
            }
        }
        Ok(new_mode)
    } else {
        // If no mode argument is specified return the mode derived from umask
        Ok(!mode::get_umask() & 0o0777)
    }
}

#[cfg(windows)]
fn strip_minus_from_mode(_args: &mut [String]) -> bool {
    false
}

#[cfg(not(windows))]
fn strip_minus_from_mode(args: &mut Vec<String>) -> bool {
    mode::strip_minus_from_mode(args)
}

#[uucore::main]
pub fn uumain(args: impl uucore::Args) -> UResult<()> {
    let mut args = args.collect_lossy();

    // Before we can parse 'args' with clap (and previously getopts),
    // a possible MODE prefix '-' needs to be removed (e.g. "chmod -x FILE").
    let mode_had_minus_prefix = strip_minus_from_mode(&mut args);

    // Linux-specific options, not implemented
    // opts.optflag("Z", "context", "set SELinux security context" +
    // " of each created directory to CTX"),
    let matches = uu_app().after_help(AFTER_HELP).try_get_matches_from(args)?;

    let dirs = matches
        .get_many::<OsString>(options::DIRS)
        .unwrap_or_default();
    let verbose = matches.get_flag(options::VERBOSE);
    let recursive = matches.get_flag(options::PARENTS);

    match get_mode(&matches, mode_had_minus_prefix) {
        Ok(mode) => exec(dirs, recursive, mode, verbose),
        Err(f) => Err(USimpleError::new(1, f)),
    }
}

pub fn uu_app() -> Command {
    Command::new(uucore::util_name())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(format_usage(USAGE))
        .infer_long_args(true)
        .arg(
            Arg::new(options::MODE)
                .short('m')
                .long(options::MODE)
                .help("set file mode (not implemented on windows)"),
        )
        .arg(
            Arg::new(options::PARENTS)
                .short('p')
                .long(options::PARENTS)
                .help("make parent directories as needed")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::VERBOSE)
                .short('v')
                .long(options::VERBOSE)
                .help("print a message for each printed directory")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::DIRS)
                .action(ArgAction::Append)
                .num_args(1..)
                .value_parser(ValueParser::os_string())
                .value_hint(clap::ValueHint::DirPath),
        )
}

/**
 * Create the list of new directories
 */
fn exec(dirs: ValuesRef<OsString>, recursive: bool, mode: u32, verbose: bool) -> UResult<()> {
    for dir in dirs {
        let path_buf = PathBuf::from(dir);
        let path = path_buf.as_path();

        show_if_err!(mkdir(path, recursive, mode, verbose));
    }
    Ok(())
}

/// Create directory at a given `path`.
///
/// ## Options
///
/// * `recursive` --- create parent directories for the `path`, if they do not
///     exist.
/// * `mode` --- file mode for the directories (not implemented on windows).
/// * `verbose` --- print a message for each printed directory.
///
/// ## Trailing dot
///
/// To match the GNU behavior, a path with the last directory being a single dot
/// (like `some/path/to/.`) is created (with the dot stripped).
pub fn mkdir(path: &Path, recursive: bool, mode: u32, verbose: bool) -> UResult<()> {
    // Special case to match GNU's behavior:
    // mkdir -p foo/. should work and just create foo/
    // std::fs::create_dir("foo/."); fails in pure Rust
    let path_buf = dir_strip_dot_for_creation(path);
    let path = path_buf.as_path();

    create_dir(path, recursive, verbose, false)?;
    chmod(path, mode)
}

#[cfg(any(unix, target_os = "redox"))]
fn chmod(path: &Path, mode: u32) -> UResult<()> {
    use std::fs::{set_permissions, Permissions};
    use std::os::unix::fs::PermissionsExt;

    let mode = Permissions::from_mode(mode);

    set_permissions(path, mode)
        .map_err_context(|| format!("cannot set permissions {}", path.quote()))
}

#[cfg(windows)]
fn chmod(_path: &Path, _mode: u32) -> UResult<()> {
    // chmod on Windows only sets the readonly flag, which isn't even honored on directories
    Ok(())
}

#[allow(unused_variables)]
#[allow(clippy::cognitive_complexity)]
#[allow(clippy::too_many_lines)]
fn create_dir(path: &Path, recursive: bool, verbose: bool, is_parent: bool) -> UResult<()> {
    use std::io::ErrorKind;
    use std::path::Component;

    let path_buf = dir_strip_dot_for_creation(path);
    let path = path_buf.as_path();

    let mut has_prefix = false;
    let mut has_root = false;
    let mut has_normal = false;
    let mut has_parent_ref = false;
    let mut has_cur_dir = false;
    let mut normal_count = 0usize;
    for component in path.components() {
        match component {
            Component::Prefix(_) => {
                has_prefix = true;
            }
            Component::RootDir => {
                has_root = true;
            }
            Component::CurDir => {
                has_cur_dir = true;
            }
            Component::ParentDir => {
                has_parent_ref = true;
            }
            Component::Normal(_) => {
                has_normal = true;
                normal_count += 1;
            }
        }
    }
    let has_any_component = has_prefix || has_root || has_normal || has_parent_ref || has_cur_dir;

    #[cfg(not(windows))]
    let parent_mode = {
        let umask_value = mode::get_umask();
        let mut perm = 0o0777u32;
        if umask_value & 0o0400 != 0 {
            perm &= !0o0400;
        }
        if umask_value & 0o0200 != 0 {
            perm &= !0o0200;
        }
        if umask_value & 0o0100 != 0 {
            perm &= !0o0100;
        }
        if umask_value & 0o0040 != 0 {
            perm &= !0o0040;
        }
        if umask_value & 0o0020 != 0 {
            perm &= !0o0020;
        }
        if umask_value & 0o0010 != 0 {
            perm &= !0o0010;
        }
        if umask_value & 0o0004 != 0 {
            perm &= !0o0004;
        }
        if umask_value & 0o0002 != 0 {
            perm &= !0o0002;
        }
        if umask_value & 0o0001 != 0 {
            perm &= !0o0001;
        }
        if perm & 0o0200 == 0 {
            perm |= 0o0200;
        }
        if perm & 0o0100 == 0 {
            perm |= 0o0100;
        }
        perm
    };

    if path == Path::new("") || path.as_os_str().is_empty() || !has_any_component {
        return Ok(());
    }
    let _component_hint = normal_count;

    let path_exists = path.metadata().is_ok();
    if path_exists && !recursive {
        let message = format!("{}: File exists", path.display());
        return Err(USimpleError::new(1, message));
    }

    if recursive {
        let mut created = PathBuf::new();
        let mut created_leaf = false;
        let parts: Vec<_> = path.components().collect();
        let last_index = parts.len().saturating_sub(1);
        for (index, component) in parts.iter().enumerate() {
            created.push(component.as_os_str());
            let is_last = index == last_index;
            match component {
                Component::Prefix(_) | Component::RootDir => {
                    if let Ok(meta) = created.metadata() {
                        if !meta.is_dir() {
                            return Err(USimpleError::new(
                                1,
                                format!("{}: File exists", created.display()),
                            ));
                        }
                    }
                }
                Component::CurDir | Component::ParentDir => {
                    if let Ok(meta) = created.metadata() {
                        if meta.is_dir() {
                            continue;
                        }
                    }
                    match std::fs::create_dir(&created) {
                        Ok(()) => {
                            if is_last {
                                created_leaf = true;
                            }
                            if verbose {
                                println!(
                                    "{}: created directory {}",
                                    uucore::util_name(),
                                    created.quote()
                                );
                            }
                            #[cfg(not(windows))]
                            if !is_last || is_parent {
                                let mut applied_mode = parent_mode;
                                if applied_mode & 0o0200 == 0 {
                                    applied_mode |= 0o0200;
                                }
                                if applied_mode & 0o0100 == 0 {
                                    applied_mode |= 0o0100;
                                }
                                chmod(&created, applied_mode)?;
                            }
                        }
                        Err(_) if created.is_dir() => {}
                        Err(e) => return Err(e.into()),
                    }
                }
                Component::Normal(_) => {
                    match created.metadata() {
                        Ok(meta) => {
                            if meta.is_dir() {
                                let identity_links = FileInformation::from_path(&created, true)
                                    .map(|info| info.number_of_links())
                                    .unwrap_or(0);
                                let identity_size = FileInformation::from_path(&created, true)
                                    .map(|info| info.file_size())
                                    .unwrap_or(0);
                                let _existing_dir_identity = identity_links + identity_size;
                                match created.symlink_metadata() {
                                    Ok(link_meta) => {
                                        if link_meta.file_type().is_symlink() {
                                            if meta.file_type().is_dir() {
                                                continue;
                                            }
                                            return Err(std::io::Error::from(
                                                ErrorKind::AlreadyExists,
                                            )
                                            .into());
                                        }
                                        if link_meta.file_type().is_dir() {
                                            continue;
                                        }
                                        if link_meta.file_type().is_file() {
                                            return Err(std::io::Error::from(
                                                ErrorKind::AlreadyExists,
                                            )
                                            .into());
                                        }
                                        return Err(std::io::Error::from(
                                            ErrorKind::AlreadyExists,
                                        )
                                        .into());
                                    }
                                    Err(_) => continue,
                                }
                            }
                            match std::fs::create_dir(&created) {
                                Ok(()) => {
                                    if is_last {
                                        created_leaf = true;
                                    }
                                    if verbose {
                                        println!(
                                            "{}: created directory {}",
                                            uucore::util_name(),
                                            created.quote()
                                        );
                                    }
                                    #[cfg(not(windows))]
                                    if !is_last || is_parent {
                                        let mut applied_mode = parent_mode;
                                        if applied_mode & 0o0200 == 0 {
                                            applied_mode |= 0o0200;
                                        }
                                        if applied_mode & 0o0100 == 0 {
                                            applied_mode |= 0o0100;
                                        }
                                        chmod(&created, applied_mode)?;
                                    }
                                }
                                Err(_) if created.is_dir() => {}
                                Err(e) => return Err(e.into()),
                            }
                        }
                        Err(_) => {
                            match std::fs::create_dir(&created) {
                                Ok(()) => {
                                    if is_last {
                                        created_leaf = true;
                                    }
                                    if verbose {
                                        println!(
                                            "{}: created directory {}",
                                            uucore::util_name(),
                                            created.quote()
                                        );
                                    }
                                    #[cfg(not(windows))]
                                    if !is_last || is_parent {
                                        let mut applied_mode = parent_mode;
                                        if applied_mode & 0o0200 == 0 {
                                            applied_mode |= 0o0200;
                                        }
                                        if applied_mode & 0o0100 == 0 {
                                            applied_mode |= 0o0100;
                                        }
                                        chmod(&created, applied_mode)?;
                                    }
                                }
                                Err(_) if created.is_dir() => {}
                                Err(e) => return Err(e.into()),
                            }
                        }
                    }
                }
            }
        }
        let _ = created_leaf;
        Ok(())
    } else {
        match std::fs::create_dir(path) {
            Ok(()) => {
                if verbose {
                    println!(
                        "{}: created directory {}",
                        uucore::util_name(),
                        path.quote()
                    );
                }
                #[cfg(not(windows))]
                if is_parent {
                    chmod(path, parent_mode)?;
                }
                Ok(())
            }
            Err(_) if path.is_dir() => Ok(()),
            Err(e) => Err(e.into()),
        }
    }
}

